function literalEnding(root,ending,tool){
 switch(tool){
  case 'just-add':return [root,ending,'none'];
  case 'drop-e':return root.at(-1)==='e'?[root.slice(0,-1),ending,'drop-e']:null;
  case 'y-to-i':return root.at(-1)==='y'?[root.slice(0,-1)+'i',ending,'y-to-i']:null;
  case 'le-to-ly':return ending==='ly'&&root.slice(-2)==='le'?[root.slice(0,-2),'ly','le-to-ly']:null;
  case 'ic-to-ically':return ending==='ly'&&root.slice(-2)==='ic'?[root,'ally','none']:null;
 }
}
